import java.util.Scanner;

public class StudentMarksCalculator {
  public static int calculateTotal(int mark1, int mark2, int mark3) {
    return mark1 + mark2 + mark3;
  }

  public static double calculateAverage(int total) {
    return total / 3.0;
  }

  public static void displayResult(int total, double average) {
    System.out.println("========== RESULT ==========");
    System.out.println("Total Marks: " + total);
    System.out.printf("Average Marks: %.2f%n", average);
    if (average >= 40) {
      System.out.println("Status: PASS");
    } else {
      System.out.println("Status: FAIL");
    }
    System.out.println("===========================");
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int mark1 = sc.nextInt();
    int mark2 = sc.nextInt();
    int mark3 = sc.nextInt();
    int total = calculateTotal(mark1, mark2, mark3);
    double avg = calculateAverage(total);
    displayResult(total, avg);
  }
}
